A switch compares the value with every case label in turn using strict equality. The default branch is the fallback that runs when no case matched.

code:
function httpLabel(code) {
  switch (code) {
    case 200: return 'OK';
    case 201: return 'Created';
    case 204: return 'No Content';
    case 404: return 'Not Found';
    case 500: return 'Server Error';
    default: return 'unknown';
  }
}
console.log(httpLabel(200), httpLabel(204), httpLabel(500), httpLabel(418)); // OK No Content Server Error unknown

output:
OK No Content Server Error unknown

An object lookup and a switch can both hold the mapping. The printed warning is the point: keeping two copies of the same table is how they drift apart.

code:
const labels = { 200: 'OK', 404: 'Not Found', 500: 'Server Error' };
for (const code of [200, 404, 500, 418]) {
  console.log(code, labels[code] ?? 'unknown');
}
console.log('both approaches can drift apart');

output:
200 OK
404 Not Found
500 Server Error
418 unknown
both approaches can drift apart

Cases run top to bottom until one matches. The default catches both numbers outside 0 to 6 and any other type.

code:
function dayName(index) {
  switch (index) {
    case 0: return 'Sunday';
    case 1: return 'Monday';
    case 2: return 'Tuesday';
    case 3: return 'Wednesday';
    case 4: return 'Thursday';
    case 5: return 'Friday';
    case 6: return 'Saturday';
    default: return 'bad day';
  }
}
console.log(dayName(0), dayName(3), dayName(6)); // Sunday Wednesday Saturday

output:
Sunday Wednesday Saturday

A switch over the command drives the state, and the loop prints the state each turn so you can watch the machine walk through its steps.

code:
let state = 'idle';
const commands = ['start', 'pass'];
for (const command of commands) {
  switch (command) {
    case 'start': state = 'running'; break;
    case 'fail': state = 'failed'; break;
    case 'pass': state = state === 'running' ? 'passed' : 'ignored'; break;
    default: console.log('unknown command', command);
  }
  console.log(command, '->', state);
}

output:
start -> running
pass -> passed

Each case returns straight away, so there is no shared statement to fall into by accident. Division by zero is handled inside its own case.

code:
function calculate(op, a, b) {
  switch (op) {
    case '+': return a + b;
    case '-': return a - b;
    case '*': return a * b;
    case '/': return b === 0 ? 'divide by zero' : a / b;
    default: return 'unknown operator';
  }
}
console.log(calculate('+', 6, 3), calculate('-', 6, 3), calculate('*', 6, 3)); // 3 3 18
console.log(calculate('/', 6, 0), calculate('%', 6, 3)); // divide by zero unknown operator

output:
9 3 18
divide by zero unknown operator

Match the string values exactly. The default branch catches token kinds your code has never heard of.

code:
function describeToken(kind) {
  switch (kind) {
    case 'bearer': return 'bearer token';
    case 'basic': return 'basic token';
    case 'cookie': return 'cookie session';
    default: return 'no token';
  }
}
console.log(describeToken('bearer'), describeToken('cookie'), describeToken('digest'));

output:
bearer token cookie session no token

Stack several case labels on top of one another so they all jump to the same return. That is grouped matching, not fall-through.

code:
function quarterFor(month) {
  switch (month) {
    case 1: case 2: case 3: return 'Q1';
    case 4: case 5: case 6: return 'Q2';
    case 7: case 8: case 9: return 'Q3';
    case 10: case 11: case 12: return 'Q4';
    default: return 'bad month';
  }
}
console.log(quarterFor(1), quarterFor(5), quarterFor(11), quarterFor(13));

output:
Q1 Q2 Q4 bad month

typeof always returns one of a small set of strings, so a switch over it is a tidy way to name them. An array reports object, which is the surprise worth showing.

code:
function describeType(value) {
  switch (typeof value) {
    case 'string': return 'a string';
    case 'number': return 'a number';
    case 'boolean': return 'a boolean';
    case 'object': return Array.isArray(value) ? 'an array' : 'an object';
    default: return 'something else';
  }
}
for (const value of ['text', 42, true, null, [1]]) console.log(typeof value, describeType(value));

output:
string a string
number a number
boolean a boolean
object an object
object an array

One case per month keeps the table readable. February reads the leap flag from inside its own case.

code:
function daysInMonth(month, leap) {
  switch (month) {
    case 1: case 3: case 5: case 7: case 8: case 10: case 12: return 31;
    case 4: case 6: case 9: case 11: return 30;
    case 2: return leap ? 29 : 28;
    default: return 'bad month';
  }
}
console.log(daysInMonth(2, true), daysInMonth(2, false), daysInMonth(4), daysInMonth(13));

output:
29 28 30 bad month

The switch has no default here on purpose: the final return covers every unlisted value, which keeps the valid cases short.

code:
function gradePoint(letter) {
  switch (letter) {
    case 'A': return 4;
    case 'B': return 3;
    case 'C': return 2;
    case 'D': return 1;
    case 'F': return 0;
  }
  return -1;
}
console.log(gradePoint('A'), gradePoint('C'), gradePoint('F'), gradePoint('X'));

output:
4 2 0 -1

switch uses strict equality, and a string is never strictly equal to a number, so the string skips every numeric case and lands on default.

code:
function classify(input) {
  switch (input) {
    case 2: return 'number two';
    case 3: return 'number three';
    default: return 'default';
  }
}
console.log(classify('2')); // default
console.log(classify(2)); // number two

output:
default
number two

Every case shares one block scope, so a let declared in one case is normally visible in another. Declare it before the switch when you want that, otherwise wrap the case body in braces.

code:
let doubled;
switch (1) {
  case 1:
    doubled = 'from case one';
    break;
  case 2:
    console.log(doubled);
    break;
}
console.log(doubled); // from case one

output:
from case one

The outer switch picks the kind of event, then an inner switch picks what happened inside it. Two switches read better than an if with a flag.

code:
function handleEvent(event) {
  switch (event.type) {
    case 'click':
      switch (event.action) {
        case 'open': return 'panel opened';
        case 'close': return 'panel closed';
        default: return 'nothing to click';
      }
    case 'key':
      switch (event.action) {
        case 'save': return 'saved';
        default: return 'ignored key';
      }
    default:
      return 'unhandled event';
  }
}
console.log(handleEvent({ type: 'click', action: 'open' })); // panel opened
console.log(handleEvent({ type: 'key', action: 'flush' })); // ignored key

output:
panel opened
ignored key

One switch holds every transition. The loop feeds it a list of events, which is exactly how you drive a state machine from test code.

code:
function nextState(state, event) {
  switch (event) {
    case 'start': return 'running';
    case 'finish': return state === 'running' ? 'passed' : 'idle';
    case 'reset': return 'idle';
    default: return state;
  }
}
let state = 'idle';
for (const event of ['start', 'finish', 'reset']) {
  state = nextState(state, event);
  console.log(event, '->', state);
}

output:
start -> running
finish -> passed
reset -> idle

A plain switch can only match exact values. Putting true in the switch position turns every case label into a normal condition.

code:
function gradeBand(gpa) {
  switch (true) {
    case gpa >= 3.5: return 'excellent';
    case gpa >= 3: return 'good';
    case gpa >= 2: return 'ok';
    default: return 'needs work';
  }
}
console.log(gradeBand(3.7), gradeBand(1.8)); // excellent needs work

output:
excellent needs work

Switch on the string remainder so 0 can be matched. Anything other than 0 falls to default, which prints the number itself.

code:
function fizzbuzzSwitch(n) {
  const both = n % 15 === 0;
  const three = n % 3 === 0;
  const five = n % 5 === 0;
  switch (String(both || (three && five))) {
    case 'true': return 'FizzBuzz';
    default:
      if (three) return 'Fizz';
      if (five) return 'Buzz';
      return String(n);
  }
}
console.log([3, 5, 15].map(fizzbuzzSwitch).join(' ')); // Fizz Buzz FizzBuzz

output:
Fizz Buzz FizzBuzz

The number 0 is never strictly equal to the empty string, so default runs. This is the same strict equality rule that catches the switch on null problem.

code:
function describe(input) {
  switch (input) {
    case '': return 'empty string';
    case 0: return 'the number zero';
    default: return 'default';
  }
}
console.log(describe(0)); // default
console.log(describe('')); // empty string

output:
the number zero
empty string

Two switches let you test the boolean first and then the reason it is not a boolean. Splitting them keeps each switch short.

code:
function flagLabel(flag) {
  switch (flag) {
    case true: return 'on';
    case false: return 'off';
    default:
      switch (flag) {
        case undefined: return 'not set';
        case null: return 'null';
        default: return 'not a flag';
      }
  }
}
console.log(flagLabel(true), flagLabel(false), flagLabel(undefined));

output:
on off not set

Each case returns its own array. Building the array inside the case means each caller gets a fresh one instead of a shared value.

code:
function permissionsFor(role) {
  switch (role) {
    case 'admin': return ['read', 'write', 'delete'];
    case 'editor': return ['read', 'write'];
    case 'viewer': return ['read'];
    case 'nobody': return [];
    default: return [];
  }
}
for (const role of ['admin', 'editor', 'viewer', 'nobody']) {
  console.log(role, permissionsFor(role).join(',') || '(none)');
}

output:
admin read,write,delete
editor read,write
viewer read
nobody (none)

Switch on the unit, then do the maths in each branch. The default throws so an unknown currency can never pass silently.

code:
function formatMoney(cents, currency) {
  switch (currency) {
    case 'usd': return '$' + (cents / 100).toFixed(2);
    case 'eur': return cents.toFixed(2) + ' EUR';
    default: throw new Error('unsupported');
  }
}
console.log(formatMoney(1250, 'usd')); // $12.50
console.log(formatMoney(1250, 'eur')); // 1250.00 EUR
try {
  formatMoney(1250, 'gbp');
} catch (err) {
  console.log('threw', err.message);
}

output:
$12.50
1250.00 EUR
threw unsupported

break always jumps to the end of the nearest breakable statement, which here is the switch. The loop keeps going, so the log after the switch runs three times.

code:
for (let n = 1; n <= 3; n++) {
  switch (n) {
    case 1: console.log('one'); break;
    case 2: console.log('two'); break;
    default: console.log('many');
  }
  console.log('end of turn', n);
}

output:
one
end of turn 1
two
end of turn 2
many
end of turn 3

Divide first, then switch on the family digit. One case per family covers hundreds of status codes.

code:
function httpClass(code) {
  switch (Math.floor(code / 100)) {
    case 2: return 'success';
    case 3: return 'redirect';
    case 4: return 'client error';
    case 5: return 'server error';
    default: return 'unknown';
  }
}
console.log(httpClass(200), httpClass(404), httpClass(700)); // success client error unknown

output:
success client error unknown

A switch on one letter keeps the cases short. The value after the letter is taken from the rest of the string and validated separately.

code:
function quarterByName(name) {
  switch (name[0]) {
    case 'Q': {
      const number = Number(name.slice(1));
      return number >= 1 && number <= 4 ? 'quarter ' + number : 'unknown';
    }
    default:
      return 'unknown';
  }
}
console.log(quarterByName('Q1'), quarterByName('Q4'), quarterByName('Q9'), quarterByName('X9'));

output:
quarter 1 quarter 4 unknown unknown

Stack the case labels so a season that wraps the year end still shares one return. Check the wrap-around months first.

code:
function seasonFor(month) {
  switch (month) {
    case 12: case 1: case 2: return 'winter';
    case 3: case 4: case 5: return 'spring';
    case 6: case 7: case 8: return 'summer';
    case 9: case 10: case 11: return 'autumn';
    default: return 'unknown';
  }
}
console.log(seasonFor(1), seasonFor(7), seasonFor(13)); // winter summer unknown

output:
winter summer unknown

Split the command into a verb and its argument, then let the switch decide. Setting a flag for quit is what ends the loop cleanly.

code:
const commands = ['add 3', 'add 4', 'list', 'quit'];
let total = 0;
let running = true;
for (const command of commands) {
  const [verb, arg] = command.split(' ');
  switch (verb) {
    case 'add': total += Number(arg); break;
    case 'list': console.log('total', total); break;
    case 'quit': running = false; break;
    default: console.log('unknown', verb);
  }
  if (!running) break;
}
console.log('final total', total);

output:
total 7
final total 7

A switch on a string key is the natural shape for a lookup like this. Keep the default so bad data shows up.

code:
function speedLimit(zone) {
  switch (zone) {
    case 'slow': return 30;
    case 'city': return 50;
    case 'road': return 70;
    case 'motorway': return 130;
    default: return 'unknown';
  }
}
console.log(speedLimit('slow'), speedLimit('road'), speedLimit('parking'));

output:
30 70 unknown

The switch does the routing, the loop does the counting. One switch per line beats an if chain that grows with every new level.

code:
const lines = ['info ready', 'error timeout', 'info step 2', 'warn slow', 'error crash'];
const counts = { info: 0, warn: 0, error: 0 };
for (const line of lines) {
  switch (line.split(' ')[0]) {
    case 'info': counts.info++; break;
    case 'warn': counts.warn++; break;
    case 'error': counts.error++; break;
    default: console.log('skipped', line);
  }
}
console.log('info', counts.info, 'warn', counts.warn, 'error', counts.error);
console.log('total', lines.length);

output:
info 2 warn 1 error 2
total 5

One case per item with the price written next to it. Returning unknown item keeps the caller in control instead of crashing.

code:
function menu(order) {
  if (order === '') return 0;
  const [item, price] = order.split(' ');
  switch (item) {
    case 'pizza': return Number(price) * 1;
    case 'salad': return Number(price);
    case 'coffee': return 3;
    default: return 'unknown item';
  }
}
console.log(menu('pizza 12'), menu('salad 8'), menu('sushi 4'));

output:
12 8 unknown item

null and undefined are only loosely equal to each other, so a switch with strict matching sends each one to its own case.

code:
function describeMissing(value) {
  switch (value) {
    case null: return 'null is present';
    case undefined: return 'undefined is present';
    default: return 'a real value';
  }
}
console.log(describeMissing(null)); // null is present
console.log(describeMissing(undefined)); // undefined is present

output:
null is present
undefined is present

Cases 1 to 3 map one to one, and the default covers everything larger so new callers do not need a code change.

code:
function retryPlan(attempt) {
  switch (attempt) {
    case 1: return 'retry immediately';
    case 2: return 'wait 1s';
    case 3: return 'wait 5s';
    default: return 'stop retrying';
  }
}
console.log(retryPlan(1), '|', retryPlan(2), '|', retryPlan(3), '|', retryPlan(5));

output:
retry immediately | wait 1s | wait 5s | stop retrying

A switch per character with grouped cases keeps the vowel and consonant lists in one readable place instead of two big if conditions.

code:
const text = 'the quick brown fox';
let vowels = 0;
let consonants = 0;
for (const char of text) {
  switch (char.toLowerCase()) {
    case 'a': case 'e': case 'i': case 'o': case 'u':
      vowels++;
      break;
    case ' ':
      break;
    default:
      consonants++;
  }
}
console.log('vowels', vowels, 'consonants', consonants);

output:
vowels 5 consonants 11

Switching on one field of the object is enough. The default protects you from test data that forgot the field.

code:
function roleLabel(user) {
  switch (user.type) {
    case 'admin': return 'Administrator';
    case 'member': return 'Member';
    case 'guest': return 'Guest';
    default: return 'unknown';
  }
}
console.log(roleLabel({ type: 'admin' })); // Administrator
console.log(roleLabel({ type: 'guest' }), '|', roleLabel({})); // Guest | unknown

output:
Administrator
Guest | unknown

Stack the small cases and let the default take everything else. The switch is on a computed string, which is still just a value.

code:
function factorFor(value) {
  switch (String(value.length)) {
    case '0': return 'none';
    case '1': return 'one';
    case '2': return 'many';
    default: return 'a big pile';
  }
}
for (const value of ['', 'x', 'xy', 'xyz']) console.log(JSON.stringify(value), factorFor(value));

output:
"" none
"x" one
"xy" many
"xyz" a big pile

Matching stops at the first case that equals the value, so a and ab are never reached. Order the specific labels first when a switch sits on the same prefix.

code:
function matchPrefix(input) {
  switch (input) {
    case 'abc': return 'three letters';
    case 'ab': return 'two letters';
    case 'a': return 'one letter';
    default: return 'no match';
  }
}
console.log(matchPrefix('abc')); // three letters
console.log(matchPrefix('ab')); // two letters
console.log(matchPrefix('zz')); // no match

output:
three letters
two letters
no match

Normalise the input before switching so a leading dot or capital letter does not break the lookup.

code:
function fileTypeFor(extension) {
  switch (extension.replace('.', '').toLowerCase()) {
    case 'txt': case 'md': return 'text';
    case 'png': case 'jpg': return 'image';
    case 'zip': case 'gz': return 'archive';
    default: return 'unknown';
  }
}
console.log(fileTypeFor('png'), fileTypeFor('zip'), fileTypeFor('md'), fileTypeFor('exe'));

output:
image archive text unknown

A switch with a condition of true turns the response checks into readable case labels. Put the most specific failures first.

code:
function stateFromResponse(response) {
  switch (true) {
    case !response.ok && response.status === 0: return 'offline';
    case response.status === 401 || response.status === 403: return 'forbidden';
    case response.status === 404: return 'missing';
    case response.status === 429: return 'too many requests';
    case response.status >= 500: return 'server error';
    default: return 'ok';
  }
}
console.log(stateFromResponse({ ok: false, status: 0 })); // offline
console.log(stateFromResponse({ ok: false, status: 403 }), stateFromResponse({ ok: false, status: 429 }));

output:
offline
forbidden too many requests
